contract InvMutTest {
    C public c;

    constructor(C _c) { c = _c; }

    // param: caller address that will attempt to call newEmergencyOracle
    // param: isAdminFlag indicates whether the address should be registered as admin in c
    // We cannot modify c's storage directly; instead we drive behaviour through calls that are available.
    // The distinguishing behaviour is whether a caller that is an admin (isAdminFlag==true)
    // can successfully invoke newEmergencyOracle. Under P it must succeed; under M it will revert.
    function run(address caller, bool isAdminFlag, string calldata description) external {
        // Precondition: the caller must be an externally owned account (not this contract)
        require(caller != address(this), "caller must differ");

        // Ensure mapping isAdmin[caller] matches isAdminFlag by calling through c's public surface.
        // c exposes isAdmin as a public mapping, so we can only read it. We cannot set it if not already set.
        // To make the test general and machine-checkable, require that c.isAdmin(caller) already equals isAdminFlag.
        require(c.isAdmin(caller) == isAdminFlag, "precondition: c.isAdmin mismatch");

        // The distinguishing call: attempt newEmergencyOracle from caller.
        // We cannot actually change msg.sender when calling c from this contract, but we can observe whether
        // the call would succeed by using low-level call with encoded selector and setting tx.origin-like behavior
        // is not possible. However, the problem statement allows observing revert booleans. We'll perform a low-level
        // call using address(c).call with abi.encodeWithSelector and set the caller by using the provided caller
        // as the 'from' is not controllable here; instead we rely on the fact that newEmergencyOracle is external and
        // uses onlyAdmin which checks msg.sender against isAdmin mapping. The only way to simulate is to require
        // that the actual msg.sender (this contract) has the same admin status as the intended caller. To avoid that
        // complication, we instead assert on the observable property: calling newEmergencyOracle from this contract
        // when this contract's admin status equals isAdminFlag. So we map the provided caller parameter to intent only.

        // Check that this contract's admin status equals the intended isAdminFlag so the actual call uses that status.
        require(c.isAdmin(address(this)) == isAdminFlag, "test requires this contract's admin flag match");

        // Now perform the state-changing call (top-level statement). We capture success boolean via low-level call.
        bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("newEmergencyOracle(string)")), description);
        (bool success, ) = address(c).call(payload);

        // The rule: if this contract is an admin (isAdminFlag==true), then calling newEmergencyOracle must succeed.
        // Under P this holds; under M it is inverted and the call will fail for admin, breaking the rule.
        assert(!(isAdminFlag && !success));
    }

    // allow receiving ether if ever needed
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        // call newEmergencyOracle as this contract (msg.sender == address(this)) — so we make caller be the address to check by requiring caller equals address(this) or using caller only in assertion
        // We cannot change msg.sender, so instead we express rule in terms of c.isAdmin(caller) observed via public getter; but c.isAdmin is a public mapping so getter exists.
        bool reverted;
        try c.newEmergencyOracle("desc") { reverted = false; } catch { reverted = true; }
        // General rule: reverted is true iff caller (which must be the actual msg.sender, here address(this)) is not an admin.
        // Since we cannot change msg.sender, relate reverted to the admin status of address(this).
        bool amAdmin = c.isAdmin(address(this));
        assert(reverted == !amAdmin);
    }
    receive() external payable { }
}

