        bytes memory data;
        if (nonce == 0x00)             data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), bytes1(0x80));
        else if (nonce <= 0x7f)        data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), address(c), uint8(nonce));
        else if (nonce <= 0xff)        data = abi.encodePacked(bytes1(0xd7), bytes1(0x94), address(c), bytes1(0x81), uint8(nonce));
